			/**
			 * 설문지 점수
			 */
			function setQustnbGrdngScore() {

			    var dsQustnbMngNoList = app.lookup("dsQustnbMngNoList");

			    var colStrArray = [];

			    if (dsQustnbMngNoList.getRowCount() == 0) {
			        colStrArray.push(0);
			        colStrArray.push(0);
			        colStrArray.push(0);
			        colStrArray.push(0);
			    } else {

			        for (var i = 0; i < dsQustnbMngNoList.getRowCount(); i++) {
			//            console.log("값 = " + dsQustnbMngNoList.getValue(i, "GRDNG_SCORE"));
			            if (dsQustnbMngNoList.getValue(i, "GRDNG_SCORE") == null || dsQustnbMngNoList.getValue(i, "GRDNG_SCORE") == "") {
			                colStrArray[i] = 0;
			            } else {
			                colStrArray[i] = Number(dsQustnbMngNoList.getValue(i, "GRDNG_SCORE").toString());
			            }
			        }

			    }

			    // 선발점수(청소년 47%, 보호자 23%, 정성평가 30%
			    var calc0 = Math.round(colStrArray[0] * 0.47);
			    var calc1 = Math.round(colStrArray[0] * 0.23);
			    var calc2 = Math.round(colStrArray[0] * 0.30);
			    var calSum = calc0 + calc1 + calc2;

			    //    app.lookup("opt119").text = calc0 + " + " + calc1 + " + " + calc2 + " = " + calSum + "점";
			    //    app.lookup("opt121").text = colStrArray[0] + " / " + colStrArray[1] + " / " + colStrArray[2] + " / " + colStrArray[3];
			    //    app.lookup("opt122").text = colStrArray[0] + colStrArray[1] + colStrArray[2] + "점";
			    //    app.lookup("opt120").text = colStrArray[0] + colStrArray[1] + colStrArray[2] + colStrArray[3] + "점";

			}

