			//=================================================================================
			// [Control Event Function] 저장, 수정, 상세 요청 button 처리 프로세스 영역
			//=================================================================================
			/*
			 * "저장" 버튼(btnSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick(e) {
			    var btnSave = e.control;

			    // 입교 신청

			    // ### 설문지점수 폼 유효성 체크 ###############################################################
			    if (stateLclas == "01" && stateSclas == "0102") {
			        qustnbScoreEvlStts = util.DataMap.getValue(app, "dmAplCntDtl", "QUSTNB_SCORE_EVL_STTS");
			        // 설문지점수 그룹 폼 활성화 여부
			        if (qustnbScoreEvlStts == null || qustnbScoreEvlStts == "") {
			            util.Msg.alert(app, "서류스크리닝 폼에 평가(미선정/선정)를 \n선택해주세요.");
			            return false;
			        }

			        if (qustnbScoreEvlStts == "01") {
			            // 미선정
			            util.DataMap.setValue(app, "dmAplCntDtl", "APLY_RCPT_SRNG_SE_CD", "02");
			            util.DataMap.setValue(app, "dmAplCntDtl", "APLY_RCPT_SRNG_PRGRS_STTS_SE_CD", "0202");
			        } else if (qustnbScoreEvlStts == "02") {
			            // 선정
			            util.DataMap.setValue(app, "dmAplCntDtl", "APLY_RCPT_SRNG_SE_CD", "02");
			            util.DataMap.setValue(app, "dmAplCntDtl", "APLY_RCPT_SRNG_PRGRS_STTS_SE_CD", "0203");
			        }

			        //doPrgrsSttsStageUpdate();

			    }

			    // ### 서류점검 폼 유효성 체크 ###############################################################
			    if (stateLclas == "03" && stateSclas == "0302") {
			        // 설문지점수 그룹 폼 활성화 여부
			        if (papersSbmsnSeCd == null || papersSbmsnSeCd == "") {
			            util.Msg.alert(app, "서류점검 폼에 서류제출여부 선택 및 \n보완서류내용을 입력 해주세요.");
			            return false;
			        } else if (papersSbmsnSeCd == "0") {
			            if (util.DataMap.getValue(app, "dmAplCntDtl", "SPLMNT_PAPERS_NM").toString() == "") {
			                util.Msg.alert(app, "서류 제출 여부를 아니요로 선택 하셨습니다.  \n보완서류내용을 입력 해주세요.");
			                return false;
			            }
			        }

			    }

			    doSave();

			}

