			/*
			 * 데이트 인풋에서 before-value-change 이벤트 발생 시 호출.
			 * Dateinput의 value를 변경하여 변경된 값이 저장되기 전에 발생하는 이벤트. 다음 이벤트로 value-change가 발생합니다.
			 */
			function onDti3BeforeValueChange(e) {
			    var dti3 = e.control;

			    // 면접일자가 신청등록일자보다 작으면 안됩니다.
			    var frstRegDt = util.DataMap.getValue(app, "dmAplCntDtl", "FRST_REG_DT"); // 신청일자
			    var intrvwYmd = e.newValue; // 면접일자
			    if (Number(intrvwYmd) < Number(frstRegDt)) {
			        util.Msg.alert(app, "면접일자는 \n신청일보다 작을 수 없습니다.");
			        e.preventDefault();
			    }
			}

			/** 콤보박스 기타(99) 기타row visible True
			 * @param {String} groupId  // rowVisible 그룹 아이디
			 * @param {String} cmbId    // selectionChange 콤보박스 아이디
			 * @param {String} ipuId    // 기타입력할 인풋박스 아이디
			 */
			function formRowVisible_fn(groupId, cmbId, ipuId) {

			    /* 2022-11-24 YOO.CHI.HOON 대상자등록화면 검토 및 질의 여가부 (추가)*/
			    var vcGrdFomLot = app.lookup(groupId).getLayout();
			    var vcCmbVal = app.lookup(cmbId).value;

			    /* 기타99 기타내용 입력*/
			    if ("99" == vcCmbVal) {
			        vcGrdFomLot.setColumnVisible(1, true);
			        util.Control.setFocus(app, ipuId);
			        util.Control.setReadOnly(app, false, ipuId);

			    } else {
			        vcGrdFomLot.setColumnVisible(1, false);
			        util.Control.reset(app, ipuId);
			        util.Control.setReadOnly(app, true, ipuId);
			    }
			}

