			/** 주민번호에서 생년월일을 확인하여 생년월일 8자리 return
			 * @param {String} rrnoVal
			 */
			function rrnoBrdtChk(rrnoVal) {
			    // 2022-10-11 YOO.CHI.HOON 성별체크하면서 추가 체크확인
			    if (ValueUtil.isNull(rrnoVal)) return false;
			    var trprBrdt = "";
			    var year = 0;

			    var sRrnoBrdtNum = rrnoVal.substring(0, 6); // 생년월일 6자리
			    var iSxdcNum = Number(rrnoVal.charAt(6)); // 성별구분

			    switch (iSxdcNum) {
			        // 1900년 ~ 1999년
			        case 1:
			        case 2:
			        case 5:
			        case 6:
			            year = 19;
			            break;
			            // 2000년대
			        case 3:
			        case 4:
			        case 7:
			        case 8:
			            year = 20;
			            break;
			    }
			    trprBrdt = year + sRrnoBrdtNum;

			    return trprBrdt;
			}

			/** 주민등록번호 입력한 경우 주민등록번호의 성별과 성별 라디오버튼 동일 확인
			    1 : 1900~1999년도 태어남 남자, 내국인
			    2 : 1900~1999년도 태어남 여자, 내국인
			    3 : 2000년대출생자 남자, 내국인
			    4 : 2000년대출생자 여자, 내국인
			    5 : 1900~1999년도 태어남 남자, 외국인
			    6 : 1900~1999년도 태어남 여자, 외국인
			    7 : 2000년대출생자 남자, 외국인
			    8 : 2000년대출생자 여자, 외국인

			    주민번호에서 성별을 확인하여 성별코드 return (공통코드[남자 : M , 여자 : F])
			 * @param {String} rrnoVal
			 */
			function rrnoSxdcChk(rrnoVal) {

			    // 2022-10-11 YOO.CHI.HOON 단위테스트 결함사항 추가 ( 주민등록번호를 입력한 경우 주민등록번호로 대상자 성별 상이 체크 알림 )
			    // 주민등록번호 13자리
			    if (ValueUtil.isNull(rrnoVal)) return false;
			    var vcSxdcCd = "";

			    // 주민번호 7번째 자리
			    var iSxdcNum = Number(rrnoVal.charAt(6));
			    switch (iSxdcNum) {
			        case 1:
			        case 3:
			        case 5:
			        case 7:
			            vcSxdcCd = "M";
			            break;
			        case 2:
			        case 4:
			        case 6:
			        case 8:
			            vcSxdcCd = "F";
			            break;
			    }
			    return vcSxdcCd;
			}

